SET local check_function_bodies = off;

DROP POLICY "bsb_tenant_scope_select" ON "better_supabase"."timeline_entries";

DROP POLICY "timeline_entries_read" ON "better_supabase"."timeline_entries";

ALTER TABLE "better_supabase"."accounting_account_roles"
  DROP CONSTRAINT "accounting_account_roles_role_check";

CREATE TABLE "better_supabase"."bom_components" (
  "id"           uuid          NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"    uuid          NOT NULL,
  "bom_id"       uuid          NOT NULL,
  "position"     integer       NOT NULL DEFAULT 0,
  "variant_id"   uuid          NOT NULL,
  "quantity"     numeric(20,6) NOT NULL,
  "scrap_bps"    integer       NOT NULL DEFAULT 0,
  "operation_id" uuid,
  CONSTRAINT "bom_components_pkey" PRIMARY KEY (id),
  CONSTRAINT "bom_components_quantity_check" CHECK ((quantity > (0)::numeric)),
  CONSTRAINT "bom_components_scrap_bps_check" CHECK (((scrap_bps >= 0) AND (scrap_bps <= 10000)))
);

ALTER TABLE "better_supabase"."bom_components"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."bom_operations" (
  "id"                   uuid          NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"            uuid          NOT NULL,
  "bom_id"               uuid          NOT NULL,
  "sequence"             integer       NOT NULL,
  "work_center_id"       uuid          NOT NULL,
  "title"                text          NOT NULL,
  "setup_minutes"        numeric(10,2) NOT NULL DEFAULT 0,
  "run_minutes_per_unit" numeric(10,4) NOT NULL DEFAULT 0,
  "instructions_node_id" uuid,
  "inspection_template"  text,
  CONSTRAINT "bom_operations_bom_id_sequence_key" UNIQUE (bom_id, SEQUENCE),
  CONSTRAINT "bom_operations_inspection_template_check" CHECK (((inspection_template IS NULL) OR ((length(inspection_template) >= 1) AND (length(inspection_template) <= 63)))),
  CONSTRAINT "bom_operations_pkey" PRIMARY KEY (id),
  CONSTRAINT "bom_operations_run_minutes_per_unit_check" CHECK ((run_minutes_per_unit >= (0)::numeric)),
  CONSTRAINT "bom_operations_sequence_check" CHECK ((sequence > 0)),
  CONSTRAINT "bom_operations_setup_minutes_check" CHECK ((setup_minutes >= (0)::numeric)),
  CONSTRAINT "bom_operations_title_check" CHECK (((length(title) >= 1) AND (length(title) <= 200)))
);

ALTER TABLE "better_supabase"."bom_operations"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."boms" (
  "id"           uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"    uuid                     NOT NULL,
  "variant_id"   uuid                     NOT NULL,
  "version"      integer                  NOT NULL,
  "status"       text                     NOT NULL DEFAULT 'draft'::text,
  "quantity"     numeric(20,6)            NOT NULL DEFAULT 1,
  "note"         text,
  "activated_at" timestamp with time zone,
  "created_by"   uuid,
  "created_at"   timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"   timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "boms_note_check" CHECK (((note IS NULL) OR (length(note) <= 10000))),
  CONSTRAINT "boms_pkey" PRIMARY KEY (id),
  CONSTRAINT "boms_quantity_check" CHECK ((quantity > (0)::numeric)),
  CONSTRAINT "boms_status_check" CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'archived'::text]))),
  CONSTRAINT "boms_tenant_id_id_key" UNIQUE (tenant_id, id),
  CONSTRAINT "boms_variant_id_version_key" UNIQUE (variant_id, VERSION),
  CONSTRAINT "boms_version_check" CHECK ((version > 0))
);

ALTER TABLE "better_supabase"."boms"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."production_consumptions" (
  "id"          uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"   uuid                     NOT NULL,
  "order_id"    uuid                     NOT NULL,
  "variant_id"  uuid                     NOT NULL,
  "lot_id"      uuid,
  "serial"      text,
  "quantity"    numeric(20,6)            NOT NULL,
  "cost"        bigint                   NOT NULL DEFAULT 0,
  "currency"    character(3),
  "movement_id" uuid                     NOT NULL,
  "created_by"  uuid,
  "created_at"  timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "production_consumptions_pkey" PRIMARY KEY (id),
  CONSTRAINT "production_consumptions_quantity_check" CHECK ((quantity > (0)::numeric)),
  CONSTRAINT "production_consumptions_serial_check" CHECK (((serial IS NULL) OR ((length(serial) >= 1) AND (length(serial) <= 100))))
);

ALTER TABLE "better_supabase"."production_consumptions"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."production_order_operations" (
  "id"              uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"       uuid                     NOT NULL,
  "order_id"        uuid                     NOT NULL,
  "operation_id"    uuid,
  "sequence"        integer                  NOT NULL,
  "work_center_id"  uuid                     NOT NULL,
  "title"           text                     NOT NULL,
  "planned_minutes" numeric(12,2)            NOT NULL DEFAULT 0,
  "status"          text                     NOT NULL DEFAULT 'pending'::text,
  "started_at"      timestamp with time zone,
  "finished_at"     timestamp with time zone,
  "operator_id"     uuid,
  "minutes"         numeric(12,2),
  "inspection_id"   uuid,
  CONSTRAINT "production_order_operations_minutes_check" CHECK (((minutes IS NULL) OR (minutes >= (0)::numeric))),
  CONSTRAINT "production_order_operations_order_id_sequence_key" UNIQUE (order_id, SEQUENCE),
  CONSTRAINT "production_order_operations_pkey" PRIMARY KEY (id),
  CONSTRAINT "production_order_operations_planned_minutes_check" CHECK ((planned_minutes >= (0)::numeric)),
  CONSTRAINT "production_order_operations_sequence_check" CHECK ((sequence > 0)),
  CONSTRAINT "production_order_operations_status_check" CHECK ((status = ANY (ARRAY['pending'::text, 'in_progress'::text, 'done'::text]))),
  CONSTRAINT "production_order_operations_title_check" CHECK (((length(title) >= 1) AND (length(title) <= 200)))
);

ALTER TABLE "better_supabase"."production_order_operations"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."production_orders" (
  "id"                uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"         uuid                     NOT NULL,
  "number"            text                     NOT NULL,
  "sequence"          bigint                   NOT NULL,
  "variant_id"        uuid                     NOT NULL,
  "bom_id"            uuid                     NOT NULL,
  "quantity"          numeric(20,6)            NOT NULL,
  "location_id"       uuid                     NOT NULL,
  "due_on"            date,
  "status"            text                     NOT NULL DEFAULT 'draft'::text,
  "produced_quantity" numeric(20,6)            NOT NULL DEFAULT 0,
  "scrap_quantity"    numeric(20,6)            NOT NULL DEFAULT 0,
  "output_lot_id"     uuid,
  "material_cost"     bigint                   NOT NULL DEFAULT 0,
  "labor_cost"        bigint                   NOT NULL DEFAULT 0,
  "currency"          character(3),
  "note"              text,
  "released_at"       timestamp with time zone,
  "started_at"        timestamp with time zone,
  "completed_at"      timestamp with time zone,
  "canceled_at"       timestamp with time zone,
  "created_by"        uuid,
  "created_at"        timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"        timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "production_orders_labor_cost_check" CHECK ((labor_cost >= 0)),
  CONSTRAINT "production_orders_note_check" CHECK (((note IS NULL) OR (length(note) <= 10000))),
  CONSTRAINT "production_orders_number_check" CHECK (((length(number) >= 1) AND (length(number) <= 100))),
  CONSTRAINT "production_orders_pkey" PRIMARY KEY (id),
  CONSTRAINT "production_orders_produced_quantity_check" CHECK ((produced_quantity >= (0)::numeric)),
  CONSTRAINT "production_orders_quantity_check" CHECK ((quantity > (0)::numeric)),
  CONSTRAINT "production_orders_scrap_quantity_check" CHECK ((scrap_quantity >= (0)::numeric)),
  CONSTRAINT "production_orders_status_check" CHECK ((status = ANY (ARRAY['draft'::text, 'released'::text, 'in_progress'::text, 'done'::text, 'canceled'::text]))),
  CONSTRAINT "production_orders_tenant_id_id_key" UNIQUE (tenant_id, id),
  CONSTRAINT "production_orders_tenant_id_number_key" UNIQUE (tenant_id, number)
);

ALTER TABLE "better_supabase"."production_orders"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."stock_lot_links" (
  "tenant_id"     uuid                     NOT NULL,
  "parent_lot_id" uuid                     NOT NULL,
  "child_lot_id"  uuid                     NOT NULL,
  "order_id"      uuid                     NOT NULL,
  "quantity"      numeric(20,6)            NOT NULL,
  "created_at"    timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "stock_lot_links_pkey" PRIMARY KEY (parent_lot_id, child_lot_id, order_id),
  CONSTRAINT "stock_lot_links_quantity_check" CHECK ((quantity > (0)::numeric))
);

ALTER TABLE "better_supabase"."stock_lot_links"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."work_centers" (
  "id"            uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"     uuid                     NOT NULL,
  "name"          text                     NOT NULL,
  "asset_id"      uuid,
  "hours_per_day" numeric(5,2)             NOT NULL DEFAULT 8,
  "cost_rate"     bigint                   NOT NULL DEFAULT 0,
  "currency"      character(3),
  "archived_at"   timestamp with time zone,
  "created_at"    timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"    timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "work_centers_check" CHECK (((cost_rate = 0) OR (currency IS NOT NULL))),
  CONSTRAINT "work_centers_cost_rate_check" CHECK ((cost_rate >= 0)),
  CONSTRAINT "work_centers_currency_check" CHECK ((currency ~ '^[A-Z]{3}$'::text)),
  CONSTRAINT "work_centers_hours_per_day_check" CHECK (((hours_per_day > (0)::numeric) AND (hours_per_day <= (24)::numeric))),
  CONSTRAINT "work_centers_name_check" CHECK (((length(name) >= 1) AND (length(name) <= 200))),
  CONSTRAINT "work_centers_pkey" PRIMARY KEY (id),
  CONSTRAINT "work_centers_tenant_id_id_key" UNIQUE (tenant_id, id)
);

ALTER TABLE "better_supabase"."work_centers"
  ENABLE ROW LEVEL SECURITY;

