CREATE POLICY "bsb_tenant_scope_select" ON "better_supabase"."timeline_entries"
  AS RESTRICTIVE
  FOR SELECT
  TO PUBLIC
  USING
    (((organization_id IN ( SELECT better_supabase.member_organization_ids() AS member_organization_ids)) OR ((organization_id IN ( SELECT
    better_supabase.tenant_ids_with('timeline.read'::text) AS tenant_ids_with)) AND
    ((subject_type IS NULL) OR (subject_id IS NULL) OR (NOT (subject_type = ANY
    ('{message,conversation,channel,company,person,deal,course,post,activity,quote,work_item,employee,invoice,ledger_account,product,product_variant,order,calendar_event,booking,asset,asset_location,lease,expense_report,expense_line,donation_fund,work_order,shipment,contract,control,compliance_policy,qualification_type,risk,case,inspection,inspection_program,inspection_finding,form,production_order,work_center,care_plan,incident,content_entry,document,customer,drive_node,application,change_request,project,task}'::text[]))) OR better_supabase.activity_subject_readable(subject_type, subject_id)))));

CREATE POLICY "timeline_entries_read" ON "better_supabase"."timeline_entries"
  FOR SELECT
  TO "authenticated"
  USING
    (((organization_id IN ( SELECT better_supabase.tenant_ids_with('timeline.read'::text) AS tenant_ids_with)) AND ((subject_type IS NULL) OR (subject_id IS NULL) OR (NOT
    (subject_type = ANY
    ('{message,conversation,channel,company,person,deal,course,post,activity,quote,work_item,employee,invoice,ledger_account,product,product_variant,order,calendar_event,booking,asset,asset_location,lease,expense_report,expense_line,donation_fund,work_order,shipment,contract,control,compliance_policy,qualification_type,risk,case,inspection,inspection_program,inspection_finding,form,production_order,work_center,care_plan,incident,content_entry,document,customer,drive_node,application,change_request,project,task}'::text[]))) OR better_supabase.activity_subject_readable(subject_type, subject_id))));

